    mov     0xa0000000, d1
    mov     d0, (0x10, sp)
    clr     d0
    call    TgVoiceRegWrite_entry, [d2,d3], 8
    mov     (4, a2), d0
    mov     0xa0020000, d1
    mov     d0, (0x10, sp)
    clr     d0
    call    TgVoiceRegWrite_entry, [d2,d3], 8
    mov     (8, a2), d0
