    mov     (0xc, a2), d0
    mov     0xa0060000, d1
    mov     d0, (0x10, sp)
    clr     d0
    call    TgVoiceRegWrite_entry, [d2,d3], 8
    movhu   (0x10, a2), d0
    mov     0xa0080000, d1
    mov     d0, (0x10, sp)
    clr     d0
    call    TgVoiceRegWrite_entry, [d2,d3], 8
loc_4C037FB8:
    ret     [a2], 0x18
